from __future__ import annotations

import asyncio
import pytest

import tests.llm_router.bdd._support as bdd_support
import tests.llm_router.support.builders as builders
import llm_router

pytestmark = pytest.mark.verification_kind("unit")


def _resolve_router():
    """Instantiate a router runtime with at least two routes."""
    # 1. Try builders
    for name in ("build_router", "make_router", "create_router"):
        factory = getattr(builders, name, None)
        if callable(factory):
            for kwargs in (
                {},
                {"spec": "primary,fallback"},
                {"routes": ("primary", "fallback")},
            ):
                try:
                    return factory(**kwargs)
                except Exception:
                    continue

    if hasattr(builders, "RouterBuilder"):
        try:
            return builders.RouterBuilder().build()
        except Exception:
            pass

    # 2. Try bdd_support
    for name in ("create_router", "build_router", "make_router"):
        factory = getattr(bdd_support, name, None)
        if callable(factory):
            for kwargs in ({}, {"spec": "primary,fallback"}):
                try:
                    return factory(**kwargs)
                except Exception:
                    continue

    # 3. Try llm_router.LLMRouter
    llm_router_cls = getattr(llm_router, "LLMRouter", None)
    if llm_router_cls is not None:
        for spec in ("primary,fallback", ["primary", "fallback"]):
            try:
                return llm_router_cls(spec=spec)
            except Exception:
                try:
                    return llm_router_cls(spec)
                except Exception:
                    continue

    msg = "Unable to instantiate router through project types."
    raise RuntimeError(msg)


def _build_mock_response():
    """Build a provider-neutral response without network."""
    for name in ("build_response", "make_response", "create_response"):
        factory = getattr(builders, name, None)
        if callable(factory):
            try:
                return factory(text="Normalized async text response")
            except Exception:
                try:
                    return factory("Normalized async text response")
                except Exception:
                    try:
                        return factory()
                    except Exception:
                        pass
    from dataclasses import dataclass

    @dataclass
    class _MockResponse:
        text: str = "Normalized async text response"
        content: str = "Normalized async text response"

    return _MockResponse()


@pytest.mark.asyncio
@pytest.mark.verifies("REQ_ASYNC_PROVIDER_EXECUTION[revision==1]")
async def test_async_rate_limited_first_route_blocks_and_falls_back():
    """Check that an async route with positive wait is blocked rather than executed."""
    router = _resolve_router()
    runtime = getattr(router, "_runtime", router)

    # Wrap the router's executor / call method to prevent network access and record calls
    orig_call_async = getattr(runtime, "_call_async_with_timeout", None)
    called_routes = []
    called_requests = []
    mock_resp = _build_mock_response()

    async def mock_call_async_with_timeout(request, timeout_seconds=None):
        called_requests.append(request)
        route = getattr(request, "route", None)
        called_routes.append(route)
        if orig_call_async is not None:
            try:
                # If the executor was already a mock/unit test fixture, try it
                return await orig_call_async(request, timeout_seconds=timeout_seconds)
            except Exception:
                pass
        return mock_resp

    runtime._call_async_with_timeout = mock_call_async_with_timeout

    # Prepare request wrapping: first route has a positive wait (rate-limited), second route is free
    orig_prepare = runtime._prepare_request
    prepare_count = 0
    first_route_ref = None
    rate_limited_wait = 5.0

    def mock_prepare_request(*args, **kwargs):
        nonlocal prepare_count, first_route_ref
        request, _ = orig_prepare(*args, **kwargs)
        prepare_count += 1
        route = kwargs.get("route") or (args[1] if len(args) > 1 else getattr(request, "route", None))
        if prepare_count == 1:
            first_route_ref = route
            return request, rate_limited_wait
        return request, 0.0

    runtime._prepare_request = mock_prepare_request

    # Execute async query through public or runtime interface
    content = "Hello, testing async rate-limited fallback."
    if hasattr(router, "aquery"):
        result = await router.aquery(content=content)
    elif hasattr(runtime, "aquery"):
        result = await runtime.aquery(content=content)
    else:
        result = await runtime._run_async(content=content, call_overrides={})

    # Verification:
    # 1. The blocked route's provider is NOT called right away
    assert first_route_ref is not None, "First route should have been prepared"
    assert first_route_ref not in called_routes, (
        f"Rate-limited route {first_route_ref} was called right away instead of being blocked"
    )

    # 2. The free route answers
    assert len(called_routes) >= 1, "The free route's provider should have been called"

    # 3. The response traces include the blocked attempt with its wait time
    traces = getattr(result, "traces", None)
    if traces is None and hasattr(result, "routing_traces"):
        traces = getattr(result, "routing_traces")
    assert traces is not None, "Result contract must expose traces"

    blocked_traces = [
        t for t in traces
        if getattr(t, "wait_seconds", 0.0) == rate_limited_wait
        or getattr(t, "status", None) == "blocked"
    ]
    assert len(blocked_traces) >= 1, (
        f"Expected blocked attempt trace with wait_seconds={rate_limited_wait}, got traces: {traces}"
    )
